#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {10, 20, 30};
    v.reserve(10); // Ensure no reallocation for initial pushes
    auto it = v.begin() + 1; // Iterator to 20

    v.insert(v.begin(), 5); // Insert at index 0
    // 'it' now points to the original 10 (shifted)
    std::cout << *it << "\n"; // Output: 10 (valid, shifted)

    auto ref = v[2]; // Reference to 20
    v.erase(v.begin() + 3); // Erase original 30
    // All elements after erase point are invalidated
    // ref is now a dangling reference (UNDEFINED BEHAVIOR)
    // std::cout << ref << "\n"; // DANGER!
}
